import express, { type NextFunction, type Request, type Response } from 'express';
import cors from 'cors';
import helmet from 'helmet';
import rateLimit from 'express-rate-limit';
import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';
import { z } from 'zod';
import { resolve } from 'node:path';
import { existsSync } from 'node:fs';
import type { ResultSetHeader, RowDataPacket } from 'mysql2';
import { env } from './config.js';
import { db, initializeDatabase, rows, transaction } from './db.js';
import { authenticate, type AuthRequest } from './middleware/auth.js';
import { abortRun, getDataset, getRun, startActor } from './services/apify.js';
import { engagement, normalizePost, normalizeUsername } from './services/normalizer.js';
import {decryptSecret,encryptSecret,generateProfileAnalysis,testAiConnection,type AiProvider} from './services/ai.js';
import {sendSmtpTest,type SmtpConfiguration} from './services/email.js';

const app = express();
app.set('trust proxy', 1);
app.use(helmet({ contentSecurityPolicy: env.NODE_ENV === 'production' ? { directives: {
  defaultSrc:["'self'"],baseUri:["'self'"],fontSrc:["'self'",'https:','data:'],formAction:["'self'"],frameAncestors:["'self'"],
  imgSrc:["'self'",'data:','https://*.cdninstagram.com','https://*.fbcdn.net'],mediaSrc:["'self'",'blob:','https://*.cdninstagram.com','https://*.fbcdn.net'],
  objectSrc:["'none'"],scriptSrc:["'self'"],scriptSrcAttr:["'none'"],styleSrc:["'self'",'https:',"'unsafe-inline'"],upgradeInsecureRequests:[]
} } : false }));
app.use(cors({ origin: env.FRONTEND_URL.split(',').map(x => x.trim()), credentials: true }));
app.use(express.json({ limit: '2mb' }));
app.use('/api', rateLimit({ windowMs: 60_000, limit: 180, standardHeaders: true, legacyHeaders: false }));

const wrap = (handler: (req: AuthRequest, res: Response) => Promise<unknown>) => (req: AuthRequest, res: Response, next: NextFunction) => Promise.resolve(handler(req, res)).catch(next);
const idOf = (req: Request) => z.coerce.number().int().positive().parse(req.params.id);
const profileSchema = z.object({ username: z.string().min(1).max(300), internalName: z.string().max(120).optional().nullable(), isActive: z.boolean().optional() });
const collectSchema = z.object({ type: z.enum(['profile_details','posts','stories','comments','full']).default('full'), limit: z.number().int().min(1).max(500).default(100), newerThan: z.string().max(50).default('30 days') });
const collectionPeriodSchema=z.string().trim().min(3).max(50).refine(value=>/^\d+\s+(minutes?|hours?|days?|weeks?|months?|years?)$/i.test(value)||/^\d{4}-\d{2}-\d{2}(?:T.*)?$/.test(value),{message:'Use um período como 45 days, 6 months ou uma data como 2026-01-01.'});
const collectionSettingsSchema=z.object({resultsLimit:z.number().int().min(1).max(500),onlyPostsNewerThan:collectionPeriodSchema,postsUntil:z.string().regex(/^\d{4}-\d{2}-\d{2}$/).nullable().optional()}).superRefine((value,context)=>{if(value.postsUntil){if(!/^\d{4}-\d{2}-\d{2}$/.test(value.onlyPostsNewerThan))context.addIssue({code:'custom',path:['onlyPostsNewerThan'],message:'Para usar data final, informe uma data inicial.'});else if(value.postsUntil<value.onlyPostsNewerThan)context.addIssue({code:'custom',path:['postsUntil'],message:'A data final deve ser igual ou posterior à inicial.'});}});
type CollectionInput=z.infer<typeof collectSchema>&{olderThan:string|null};
const screenKeys=['dashboard','profiles','comparisons','comparison_groups','collections','settings','system_users','access_profiles'] as const;
const screenKeySchema=z.enum(screenKeys);
const accessProfileSchema=z.object({name:z.string().trim().min(2).max(120),description:z.string().trim().max(500).optional().nullable(),isActive:z.boolean().default(true),permissions:z.array(screenKeySchema).default([])});
const userSchema=z.object({name:z.string().trim().min(2).max(120),email:z.string().email().max(190),password:z.string().min(8).max(200).optional(),role:z.enum(['admin','user']).default('user'),accessProfileId:z.number().int().positive().nullable().optional(),isActive:z.boolean().default(true)}).superRefine((value,context)=>{if(value.role==='user'&&!value.accessProfileId)context.addIssue({code:'custom',path:['accessProfileId'],message:'Selecione um perfil de acesso para o usuário.'});});

app.get('/api/health', wrap(async (_req, res) => {
  await db.query('SELECT 1'); res.json({ status: 'ok', database: 'connected', timestamp: new Date().toISOString() });
}));
app.post('/api/auth/login', rateLimit({ windowMs: 15 * 60_000, limit: 10 }), wrap(async (req, res) => {
  const input = z.object({ email: z.string().email(), password: z.string().min(1) }).parse(req.body);
  const users = await rows<(RowDataPacket & { id:number; name:string; email:string; role:string; password_hash:string; access_profile_id:number|null; access_profile_name:string|null; permissions:string|null })[]>(`SELECT u.*,ap.name access_profile_name,GROUP_CONCAT(app.screen_key) permissions FROM users u LEFT JOIN access_profiles ap ON ap.id=u.access_profile_id AND ap.is_active=1 LEFT JOIN access_profile_permissions app ON app.access_profile_id=ap.id WHERE u.email=? AND u.is_active=1 GROUP BY u.id LIMIT 1`, [input.email.toLowerCase()]);
  const user = users[0];
  if (!user || !(await bcrypt.compare(input.password, user.password_hash))) return res.status(401).json({ message: 'E-mail ou senha incorretos.' });
  const token = jwt.sign({ id: user.id, email: user.email, role: user.role }, env.JWT_SECRET, { expiresIn: env.JWT_EXPIRES_IN as jwt.SignOptions['expiresIn'] });
  res.json({ token, user: { id:user.id, name:user.name, email:user.email, role:user.role,accessProfileId:user.access_profile_id?Number(user.access_profile_id):null,accessProfileName:user.access_profile_name,permissions:user.role==='admin'?[...screenKeys]:String(user.permissions||'').split(',').filter(Boolean) } });
}));
app.get('/api/auth/me', authenticate, wrap(async (req, res) => {
  const users = await rows<RowDataPacket[]>('SELECT u.id,u.name,u.email,u.role,u.access_profile_id accessProfileId,ap.name accessProfileName FROM users u LEFT JOIN access_profiles ap ON ap.id=u.access_profile_id WHERE u.id=? AND u.is_active=1', [req.user!.id]); res.json({...users[0],permissions:req.user!.role==='admin'?[...screenKeys]:req.user!.permissions});
}));
app.post('/api/auth/logout', authenticate, (_req, res) => res.status(204).end());
app.get('/api/media/profiles/:id/picture',wrap(async(req,res)=>{const profiles=await rows<(RowDataPacket&{profile_picture_url:string|null})[]>('SELECT profile_picture_url FROM instagram_profiles WHERE id=?',[idOf(req)]);const picture=profiles[0]?.profile_picture_url;if(!picture)return res.status(404).end();const url=new URL(picture);if(url.protocol!=='https:'||(!url.hostname.endsWith('.cdninstagram.com')&&!url.hostname.endsWith('.fbcdn.net')))return res.status(400).end();const response=await fetch(url,{headers:{'user-agent':'Mozilla/5.0'}});if(!response.ok)return res.status(404).end();const contentType=response.headers.get('content-type')||'image/jpeg';if(!contentType.startsWith('image/'))return res.status(415).end();res.set({'Content-Type':contentType,'Cache-Control':'public, max-age=3600, stale-while-revalidate=86400'});res.send(Buffer.from(await response.arrayBuffer()));}));

app.use('/api', authenticate);
const permissionsForRequest=(req:AuthRequest):string[]=>{const path=req.path;if(path==='/access-profiles'&&req.method==='GET')return['access_profiles','system_users'];if(path.startsWith('/access-profiles'))return['access_profiles'];if(path.startsWith('/system-users'))return['system_users'];if(/^\/profiles\/\d+\/set-base$/.test(path))return['dashboard'];if(/^\/profiles\/\d+\/collect$/.test(path))return['profiles'];if(path==='/profiles'&&req.method==='GET')return['profiles','comparison_groups','collections','comparisons'];if(path.startsWith('/comparison-groups'))return['comparison_groups'];if(path.startsWith('/comparisons'))return['comparisons'];if(path.startsWith('/collection-settings')||path.startsWith('/email/settings'))return['settings'];if(path.startsWith('/collections')||path.startsWith('/runs'))return['collections'];if(path.startsWith('/ai/settings'))return['settings'];if(path.startsWith('/ai/analysis')||path.startsWith('/ai/analyze')||path.startsWith('/dashboard'))return['dashboard'];if(path.startsWith('/posts')||path.startsWith('/profiles'))return['profiles'];return[];};
app.use('/api',(req:AuthRequest,res,next)=>{if(req.user?.role==='admin')return next();const permissions=permissionsForRequest(req);if(!permissions.length||permissions.some(permission=>req.user?.permissions.includes(permission)))return next();return res.status(403).json({message:'Seu perfil de acesso não permite abrir esta área.'});});
const requireManagement=(...permissions:Array<'system_users'|'access_profiles'>)=>(req:AuthRequest,res:Response,next:NextFunction)=>req.user?.role==='admin'||permissions.some(permission=>req.user?.permissions.includes(permission))?next():res.status(403).json({message:'Seu perfil não permite gerenciar esta área.'});
async function validateUserAccessProfile(role:'admin'|'user',accessProfileId:number|null|undefined){if(role==='admin')return;const found=await rows<RowDataPacket[]>('SELECT id FROM access_profiles WHERE id=? AND is_active=1',[accessProfileId]);if(!found[0])throw Object.assign(new Error('Selecione um perfil de acesso ativo.'),{status:400});}

app.get('/api/access-profiles',requireManagement('access_profiles','system_users'),wrap(async(_req,res)=>{const profiles=await rows<RowDataPacket[]>(`SELECT ap.*,COUNT(DISTINCT u.id) user_count,COALESCE(GROUP_CONCAT(DISTINCT app.screen_key ORDER BY app.screen_key SEPARATOR ','),'') permissions FROM access_profiles ap LEFT JOIN users u ON u.access_profile_id=ap.id LEFT JOIN access_profile_permissions app ON app.access_profile_id=ap.id GROUP BY ap.id ORDER BY ap.name`);res.json(profiles.map((profile:any)=>({...profile,is_active:Boolean(profile.is_active),permissions:String(profile.permissions||'').split(',').filter(Boolean),user_count:Number(profile.user_count)})));}));
app.post('/api/access-profiles',requireManagement('access_profiles'),wrap(async(req,res)=>{const input=accessProfileSchema.parse(req.body);const id=await transaction(async connection=>{const [created]=await connection.execute<ResultSetHeader>('INSERT INTO access_profiles(name,description,is_active,created_by) VALUES(?,?,?,?)',[input.name,input.description||null,input.isActive,req.user!.id]);for(const permission of [...new Set(input.permissions)])await connection.execute('INSERT INTO access_profile_permissions(access_profile_id,screen_key) VALUES(?,?)',[created.insertId,permission]);return Number(created.insertId)});res.status(201).json({id});}));
app.put('/api/access-profiles/:id',requireManagement('access_profiles'),wrap(async(req,res)=>{const profileId=idOf(req);const input=accessProfileSchema.parse(req.body);await transaction(async connection=>{const [updated]=await connection.execute<ResultSetHeader>('UPDATE access_profiles SET name=?,description=?,is_active=? WHERE id=?',[input.name,input.description||null,input.isActive,profileId]);if(!updated.affectedRows)throw Object.assign(new Error('Perfil de acesso não encontrado.'),{status:404});await connection.execute('DELETE FROM access_profile_permissions WHERE access_profile_id=?',[profileId]);for(const permission of [...new Set(input.permissions)])await connection.execute('INSERT INTO access_profile_permissions(access_profile_id,screen_key) VALUES(?,?)',[profileId,permission]);});res.status(204).end();}));
app.delete('/api/access-profiles/:id',requireManagement('access_profiles'),wrap(async(req,res)=>{const profileId=idOf(req);const assigned=await rows<(RowDataPacket&{total:number})[]>('SELECT COUNT(*) total FROM users WHERE access_profile_id=?',[profileId]);if(Number(assigned[0]?.total))return res.status(409).json({message:'Remova ou altere os usuários associados antes de excluir este perfil.'});await db.execute('DELETE FROM access_profiles WHERE id=?',[profileId]);res.status(204).end();}));

app.get('/api/system-users',requireManagement('system_users'),wrap(async(req,res)=>{const where=req.user!.role==='admin'?'':`WHERE u.role='user'`;res.json(await rows<RowDataPacket[]>(`SELECT u.id,u.name,u.email,u.role,u.is_active,u.access_profile_id,ap.name access_profile_name,u.created_at,u.updated_at FROM users u LEFT JOIN access_profiles ap ON ap.id=u.access_profile_id ${where} ORDER BY u.name`));}));
app.post('/api/system-users',requireManagement('system_users'),wrap(async(req,res)=>{const input=userSchema.safeExtend({password:z.string().min(8,'A senha deve ter pelo menos 8 caracteres.').max(200)}).parse(req.body);if(req.user!.role!=='admin'&&input.role==='admin')return res.status(403).json({message:'Somente administradores podem criar outras contas administrativas.'});await validateUserAccessProfile(input.role,input.accessProfileId);const passwordHash=await bcrypt.hash(input.password,12);const values:any[]=[input.name,input.email.toLowerCase(),passwordHash,input.role,input.role==='admin'?null:input.accessProfileId,input.isActive];try{const [created]=await db.execute<ResultSetHeader>('INSERT INTO users(name,email,password_hash,role,access_profile_id,is_active) VALUES(?,?,?,?,?,?)',values);res.status(201).json({id:Number(created.insertId)});}catch(error:any){if(error.code==='ER_DUP_ENTRY')return res.status(409).json({message:'Já existe um usuário com este e-mail.'});if(error.code==='ER_NO_REFERENCED_ROW_2')return res.status(400).json({message:'O perfil de acesso selecionado não está mais disponível.'});throw error;}}));
app.put('/api/system-users/:id',requireManagement('system_users'),wrap(async(req,res)=>{const userId=idOf(req);const input=userSchema.parse(req.body);const target=await rows<(RowDataPacket&{role:string})[]>('SELECT role FROM users WHERE id=?',[userId]);if(!target[0])return res.status(404).json({message:'Usuário não encontrado.'});if(req.user!.role!=='admin'&&(userId===req.user!.id||target[0].role==='admin'||input.role==='admin'))return res.status(403).json({message:'Este usuário só pode ser alterado por um administrador.'});if(userId===req.user!.id&&(!input.isActive||input.role!=='admin'))return res.status(400).json({message:'Você não pode desativar ou remover seu próprio acesso administrativo.'});await validateUserAccessProfile(input.role,input.accessProfileId);const fields=['name=?','email=?','role=?','access_profile_id=?','is_active=?'];const values:any[]=[input.name,input.email.toLowerCase(),input.role,input.role==='admin'?null:input.accessProfileId,input.isActive];if(input.password){fields.push('password_hash=?');values.push(await bcrypt.hash(input.password,12))}values.push(userId);try{await db.execute(`UPDATE users SET ${fields.join(',')} WHERE id=?`,values);res.status(204).end();}catch(error:any){if(error.code==='ER_DUP_ENTRY')return res.status(409).json({message:'Já existe um usuário com este e-mail.'});throw error;}}));
app.delete('/api/system-users/:id',requireManagement('system_users'),wrap(async(req,res)=>{const userId=idOf(req);if(userId===req.user!.id)return res.status(400).json({message:'Você não pode excluir seu próprio usuário.'});const target=await rows<(RowDataPacket&{role:string})[]>('SELECT role FROM users WHERE id=?',[userId]);if(!target[0])return res.status(404).json({message:'Usuário não encontrado.'});if(req.user!.role!=='admin'&&target[0].role==='admin')return res.status(403).json({message:'Somente administradores podem excluir outra conta administrativa.'});await db.execute('DELETE FROM users WHERE id=?',[userId]);res.status(204).end();}));
const aiSettingsSchema=z.object({enabled:z.boolean(),provider:z.enum(['openai','anthropic']),openaiModel:z.string().trim().min(2).max(100),anthropicModel:z.string().trim().min(2).max(100),openaiApiKey:z.string().trim().max(500).optional(),anthropicApiKey:z.string().trim().max(500).optional()});
type AiSettingsRow=RowDataPacket&{ai_enabled:number;ai_provider:AiProvider;openai_model:string;anthropic_model:string;openai_api_key_encrypted:string|null;anthropic_api_key_encrypted:string|null;ai_last_tested_at:Date|null;base_profile_id:number|null};
async function getAiSettingsRow(){const found=await rows<AiSettingsRow[]>('SELECT base_profile_id,ai_enabled,ai_provider,openai_model,anthropic_model,openai_api_key_encrypted,anthropic_api_key_encrypted,ai_last_tested_at FROM workspace_settings WHERE id=1');return found[0]||{ai_enabled:0,ai_provider:'openai',openai_model:'gpt-5.6-sol',anthropic_model:'claude-sonnet-4-6',openai_api_key_encrypted:null,anthropic_api_key_encrypted:null,ai_last_tested_at:null,base_profile_id:null} as AiSettingsRow}
function publicAiSettings(setting:AiSettingsRow){return{enabled:Boolean(setting.ai_enabled),provider:setting.ai_provider,openaiModel:setting.openai_model||'gpt-5.6-sol',anthropicModel:setting.anthropic_model||'claude-sonnet-4-6',openaiConfigured:Boolean(setting.openai_api_key_encrypted),anthropicConfigured:Boolean(setting.anthropic_api_key_encrypted),lastTestedAt:setting.ai_last_tested_at}}
function configuredAi(setting:AiSettingsRow,provider:AiProvider){const encrypted=provider==='openai'?setting.openai_api_key_encrypted:setting.anthropic_api_key_encrypted;if(!encrypted)throw Object.assign(new Error(`Configure a chave da ${provider==='openai'?'OpenAI':'Anthropic'} antes de continuar.`),{status:400});return{key:decryptSecret(encrypted,env.JWT_SECRET),model:provider==='openai'?setting.openai_model:setting.anthropic_model}}
app.get('/api/ai/settings',wrap(async(_req,res)=>res.json(publicAiSettings(await getAiSettingsRow()))));
app.put('/api/ai/settings',wrap(async(req,res)=>{const input=aiSettingsSchema.parse(req.body);const current=await getAiSettingsRow();const openaiEncrypted=input.openaiApiKey?encryptSecret(input.openaiApiKey,env.JWT_SECRET):current.openai_api_key_encrypted;const anthropicEncrypted=input.anthropicApiKey?encryptSecret(input.anthropicApiKey,env.JWT_SECRET):current.anthropic_api_key_encrypted;if(input.enabled&&!(input.provider==='openai'?openaiEncrypted:anthropicEncrypted))return res.status(400).json({message:'Informe a chave do provedor selecionado para ativar a IA.'});await db.execute(`INSERT INTO workspace_settings(id,ai_enabled,ai_provider,openai_model,anthropic_model,openai_api_key_encrypted,anthropic_api_key_encrypted,updated_by) VALUES(1,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE ai_enabled=VALUES(ai_enabled),ai_provider=VALUES(ai_provider),openai_model=VALUES(openai_model),anthropic_model=VALUES(anthropic_model),openai_api_key_encrypted=VALUES(openai_api_key_encrypted),anthropic_api_key_encrypted=VALUES(anthropic_api_key_encrypted),updated_by=VALUES(updated_by)`,[input.enabled,input.provider,input.openaiModel,input.anthropicModel,openaiEncrypted,anthropicEncrypted,req.user!.id]);res.json(publicAiSettings(await getAiSettingsRow()))}));
app.post('/api/ai/settings/test',rateLimit({windowMs:60_000,limit:5}),wrap(async(req,res)=>{const input=z.object({provider:z.enum(['openai','anthropic']),model:z.string().trim().min(2).max(100),apiKey:z.string().trim().max(500).optional()}).parse(req.body);const setting=await getAiSettingsRow();const key=input.apiKey||configuredAi(setting,input.provider).key;await testAiConnection(input.provider,input.model,key);await db.execute(`INSERT INTO workspace_settings(id,ai_last_tested_at,updated_by) VALUES(1,UTC_TIMESTAMP(),?) ON DUPLICATE KEY UPDATE ai_last_tested_at=UTC_TIMESTAMP(),updated_by=VALUES(updated_by)`,[req.user!.id]);res.json({ok:true,testedAt:new Date().toISOString()})}));

const emailSettingsSchema=z.object({enabled:z.boolean(),host:z.string().trim().max(255),port:z.number().int().min(1).max(65535),secure:z.boolean(),requireTls:z.boolean(),user:z.string().trim().max(255),password:z.string().max(500).optional(),fromName:z.string().trim().max(120),fromAddress:z.string().trim().email().or(z.literal('')),replyTo:z.string().trim().email().or(z.literal('')).optional(),notifyPasswords:z.boolean(),notifyReports:z.boolean(),notifySystem:z.boolean()}).superRefine((value,context)=>{if(!value.enabled)return;if(!value.host)context.addIssue({code:'custom',path:['host'],message:'Informe o servidor SMTP.'});if(!value.fromName)context.addIssue({code:'custom',path:['fromName'],message:'Informe o nome do remetente.'});if(!value.fromAddress)context.addIssue({code:'custom',path:['fromAddress'],message:'Informe o e-mail do remetente.'});});
type EmailSettingsRow=RowDataPacket&{email_enabled:number;smtp_host:string|null;smtp_port:number;smtp_secure:number;smtp_require_tls:number;smtp_user:string|null;smtp_password_encrypted:string|null;email_from_name:string|null;email_from_address:string|null;email_reply_to:string|null;email_notify_passwords:number;email_notify_reports:number;email_notify_system:number;email_last_tested_at:Date|null};
async function getEmailSettingsRow(){const found=await rows<EmailSettingsRow[]>('SELECT email_enabled,smtp_host,smtp_port,smtp_secure,smtp_require_tls,smtp_user,smtp_password_encrypted,email_from_name,email_from_address,email_reply_to,email_notify_passwords,email_notify_reports,email_notify_system,email_last_tested_at FROM workspace_settings WHERE id=1');return found[0]||{email_enabled:0,smtp_host:'',smtp_port:587,smtp_secure:0,smtp_require_tls:1,smtp_user:'',smtp_password_encrypted:null,email_from_name:'Studek Analytics',email_from_address:'',email_reply_to:'',email_notify_passwords:1,email_notify_reports:1,email_notify_system:1,email_last_tested_at:null} as EmailSettingsRow}
function publicEmailSettings(setting:EmailSettingsRow){return{enabled:Boolean(setting.email_enabled),host:setting.smtp_host||'',port:Number(setting.smtp_port||587),secure:Boolean(setting.smtp_secure),requireTls:Boolean(setting.smtp_require_tls),user:setting.smtp_user||'',passwordConfigured:Boolean(setting.smtp_password_encrypted),fromName:setting.email_from_name||'Studek Analytics',fromAddress:setting.email_from_address||'',replyTo:setting.email_reply_to||'',notifyPasswords:Boolean(setting.email_notify_passwords),notifyReports:Boolean(setting.email_notify_reports),notifySystem:Boolean(setting.email_notify_system),lastTestedAt:setting.email_last_tested_at}}
function smtpConfiguration(input:z.infer<typeof emailSettingsSchema>,encryptedPassword:string|null):SmtpConfiguration{if(!input.host||!input.fromAddress||!input.fromName)throw Object.assign(new Error('Preencha o servidor e os dados do remetente.'),{status:400});if(input.user&&!encryptedPassword)throw Object.assign(new Error('Informe a senha SMTP.'),{status:400});return{host:input.host,port:input.port,secure:input.secure,requireTls:input.requireTls,user:input.user,password:encryptedPassword?decryptSecret(encryptedPassword,env.JWT_SECRET):'',fromName:input.fromName,fromAddress:input.fromAddress,replyTo:input.replyTo||null}}
