app.put('/api/email/settings',wrap(async(req,res)=>{const input=emailSettingsSchema.parse(req.body);const current=await getEmailSettingsRow();const passwordEncrypted=input.password?encryptSecret(input.password,env.JWT_SECRET):current.smtp_password_encrypted;if(input.enabled)smtpConfiguration(input,passwordEncrypted);await db.execute(`INSERT INTO workspace_settings(id,email_enabled,smtp_host,smtp_port,smtp_secure,smtp_require_tls,smtp_user,smtp_password_encrypted,email_from_name,email_from_address,email_reply_to,email_notify_passwords,email_notify_reports,email_notify_system,updated_by) VALUES(1,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE email_enabled=VALUES(email_enabled),smtp_host=VALUES(smtp_host),smtp_port=VALUES(smtp_port),smtp_secure=VALUES(smtp_secure),smtp_require_tls=VALUES(smtp_require_tls),smtp_user=VALUES(smtp_user),smtp_password_encrypted=VALUES(smtp_password_encrypted),email_from_name=VALUES(email_from_name),email_from_address=VALUES(email_from_address),email_reply_to=VALUES(email_reply_to),email_notify_passwords=VALUES(email_notify_passwords),email_notify_reports=VALUES(email_notify_reports),email_notify_system=VALUES(email_notify_system),updated_by=VALUES(updated_by)`,[input.enabled,input.host||null,input.port,input.secure,input.requireTls,input.user||null,passwordEncrypted,input.fromName||null,input.fromAddress||null,input.replyTo||null,input.notifyPasswords,input.notifyReports,input.notifySystem,req.user!.id]);res.json(publicEmailSettings(await getEmailSettingsRow()))}));
