async function aiSourceSnapshot(profileId:number){
  const baseRows=await rows<RowDataPacket[]>(`SELECT p.id,p.username,p.full_name,p.internal_name,p.biography,p.category,p.external_url,p.last_collected_at,COALESCE(s.followers_count,0) followers,COALESCE(s.follows_count,0) following,COALESCE(s.posts_count,0) totalPosts,COALESCE(s.average_likes,0) averageLikes,COALESCE(s.average_comments,0) averageComments,COALESCE(s.average_engagement,0) averageEngagement,COALESCE(s.engagement_rate,0) engagementRate,(SELECT followers_count FROM profile_snapshots WHERE profile_id=p.id AND followers_count>0 ORDER BY collected_at LIMIT 1) firstFollowers,(SELECT COUNT(*) FROM instagram_posts ip WHERE ip.profile_id=p.id AND ip.published_at>=UTC_TIMESTAMP()-INTERVAL 30 DAY) posts30Days FROM instagram_profiles p LEFT JOIN profile_snapshots s ON s.id=(SELECT id FROM profile_snapshots WHERE profile_id=p.id ORDER BY collected_at DESC LIMIT 1) WHERE p.id=?`,[profileId]);
  const profile:any=baseRows[0];if(!profile)throw Object.assign(new Error('Perfil base não encontrado.'),{status:404});
  const grouped=await rows<(RowDataPacket&{id:number})[]>(`SELECT DISTINCT gp.profile_id id FROM comparison_group_profiles gp WHERE gp.comparison_group_id IN (SELECT comparison_group_id FROM comparison_group_profiles WHERE profile_id=?) AND gp.profile_id<>?`,[profileId,profileId]);
  const groupedIds=grouped.map(item=>Number(item.id));const competitorFilter=groupedIds.length?`p.id IN (${groupedIds.map(()=>'?').join(',')})`:'p.id<>?';const competitorValues=groupedIds.length?groupedIds:[profileId];
  const competitors=await rows<RowDataPacket[]>(`SELECT p.id,p.username,p.full_name,p.biography,p.category,p.external_url,p.last_collected_at,COALESCE(s.followers_count,0) followers,COALESCE(s.engagement_rate,0) engagementRate,COALESCE(s.average_likes,0) averageLikes,COALESCE(s.average_comments,0) averageComments,COALESCE(s.average_engagement,0) averageEngagement,(SELECT COUNT(*) FROM instagram_posts ip WHERE ip.profile_id=p.id AND ip.published_at>=UTC_TIMESTAMP()-INTERVAL 30 DAY) posts30Days FROM instagram_profiles p LEFT JOIN profile_snapshots s ON s.id=(SELECT id FROM profile_snapshots WHERE profile_id=p.id ORDER BY collected_at DESC LIMIT 1) WHERE p.is_active=1 AND ${competitorFilter} ORDER BY s.engagement_rate DESC LIMIT 7`,competitorValues);
  const analyzedProfiles=[profile,...competitors];const ids=analyzedProfiles.map(item=>Number(item.id));const marks=ids.map(()=>'?').join(',');
  const posts=await rows<RowDataPacket[]>(`SELECT ranked.* FROM (SELECT p.id,p.profile_id,p.post_type,p.content_surface,LEFT(COALESCE(p.caption,''),300) caption,p.published_at,COALESCE(m.likes_count,0) likes,COALESCE(m.comments_count,0) comments,COALESCE(m.views_count,0) views,COALESCE(m.plays_count,0) plays,COALESCE(m.engagement_count,0) engagement,COALESCE((SELECT GROUP_CONCAT(h.name ORDER BY h.name SEPARATOR ',') FROM post_hashtags ph JOIN hashtags h ON h.id=ph.hashtag_id WHERE ph.post_id=p.id),'') hashtags,ROW_NUMBER() OVER(PARTITION BY p.profile_id ORDER BY COALESCE(m.engagement_count,0) DESC) profile_rank FROM instagram_posts p LEFT JOIN post_metrics m ON m.id=(SELECT id FROM post_metrics WHERE post_id=p.id ORDER BY collected_at DESC LIMIT 1) WHERE p.profile_id IN (${marks}) AND p.published_at>=UTC_TIMESTAMP()-INTERVAL 90 DAY) ranked WHERE ranked.profile_rank<=20 ORDER BY ranked.profile_id,ranked.engagement DESC`,ids);
  const history=await rows<RowDataPacket[]>('SELECT followers_count followers,engagement_rate engagementRate,collected_at collectedAt FROM profile_snapshots WHERE profile_id=? ORDER BY collected_at DESC LIMIT 12',[profileId]);
  const weekday=(value:any)=>new Intl.DateTimeFormat('pt-BR',{weekday:'long',timeZone:'America/Sao_Paulo'}).format(new Date(value));const hour=(value:any)=>new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',hour12:false,timeZone:'America/Sao_Paulo'}).format(new Date(value)).replace(' h','h');
  const benchmarks=analyzedProfiles.map((item:any)=>{const own=(posts as any[]).filter(post=>Number(post.profile_id)===Number(item.id));const formatMap=new Map<string,{format:string;posts:number;engagement:number}>();const windowMap=new Map<string,{day:string;time:string;posts:number;engagement:number}>();const hashtagMap=new Map<string,{hashtag:string;posts:number;engagement:number}>();for(const post of own){const format=post.content_surface==='Reel'||post.post_type==='Reel'?'Reel':post.post_type==='Sidecar'?'Carrossel':post.post_type;const f=formatMap.get(format)||{format,posts:0,engagement:0};f.posts++;f.engagement+=Number(post.engagement);formatMap.set(format,f);const day=weekday(post.published_at),time=hour(post.published_at),key=`${day}:${time}`;const w=windowMap.get(key)||{day,time,posts:0,engagement:0};w.posts++;w.engagement+=Number(post.engagement);windowMap.set(key,w);for(const raw of String(post.hashtags||'').split(',').filter(Boolean)){const hashtag=`#${raw.replace(/^#/,'')}`;const h=hashtagMap.get(hashtag)||{hashtag,posts:0,engagement:0};h.posts++;h.engagement+=Number(post.engagement);hashtagMap.set(hashtag,h)}}const average=(entry:{posts:number;engagement:number})=>entry.posts?Math.round(entry.engagement/entry.posts):0;return{role:Number(item.id)===profileId?'base':'comparison',profile:{...item,followerGrowth:Number(item.followers)-Number(item.firstFollowers||item.followers)},formats:[...formatMap.values()].map(entry=>({...entry,averageEngagement:average(entry)})).sort((a,b)=>b.averageEngagement-a.averageEngagement),postingWindows:[...windowMap.values()].filter(entry=>entry.posts>=2).map(entry=>({...entry,averageEngagement:average(entry)})).sort((a,b)=>b.averageEngagement-a.averageEngagement).slice(0,6),hashtags:[...hashtagMap.values()].map(entry=>({...entry,averageEngagement:average(entry)})).sort((a,b)=>b.averageEngagement-a.averageEngagement).slice(0,15),topPosts:own.slice(0,8)}});
  return{generatedAt:new Date().toISOString(),timezone:'America/Sao_Paulo',period:'Últimos 90 dias para conteúdo; métricas atuais dos perfis',comparisonScope:groupedIds.length?'Perfis que compartilham grupo de comparação com o perfil base':'Todos os perfis ativos (nenhum grupo compartilhado encontrado)',sample:{profiles:analyzedProfiles.length,posts:(posts as any[]).length},baseProfileId:profileId,history,benchmarks};
}
type AiJobRow=RowDataPacket&{id:number;profile_id:number;provider:AiProvider;model:string;status:'queued'|'running'|'succeeded'|'failed';analysis_id:number|null;error_message:string|null;created_by:number|null;started_at:Date|null;finished_at:Date|null;created_at:Date};
function publicAiJob(job:AiJobRow|undefined){return job?{id:Number(job.id),profileId:Number(job.profile_id),provider:job.provider,model:job.model,status:job.status,analysisId:job.analysis_id?Number(job.analysis_id):null,errorMessage:job.error_message,createdAt:job.created_at,startedAt:job.started_at,finishedAt:job.finished_at}:null}
let aiWorkerRunning=false;
async function processAiQueue(){if(aiWorkerRunning)return;aiWorkerRunning=true;try{while(true){const queued=await rows<AiJobRow[]>(`SELECT * FROM ai_analysis_jobs WHERE status='queued' ORDER BY created_at LIMIT 1`);const job=queued[0];if(!job)break;const [claimed]=await db.execute<ResultSetHeader>(`UPDATE ai_analysis_jobs SET status='running',started_at=UTC_TIMESTAMP(),error_message=NULL WHERE id=? AND status='queued'`,[job.id]);if(!claimed.affectedRows)continue;try{const setting=await getAiSettingsRow();const credentials=configuredAi(setting,job.provider);const snapshot=await aiSourceSnapshot(Number(job.profile_id));const analysis=await generateProfileAnalysis(job.provider,job.model,credentials.key,snapshot);await transaction(async connection=>{const [created]=await connection.execute<ResultSetHeader>('INSERT INTO ai_profile_analyses(profile_id,provider,model,analysis_json,source_snapshot,created_by) VALUES(?,?,?,?,?,?)',[job.profile_id,job.provider,job.model,JSON.stringify(analysis),JSON.stringify(snapshot),job.created_by]);await connection.execute(`UPDATE ai_analysis_jobs SET status='succeeded',analysis_id=?,finished_at=UTC_TIMESTAMP() WHERE id=?`,[created.insertId,job.id])});}catch(error:any){const message=error?.status?String(error.message):'Falha interna ao preparar ou salvar a análise.';await db.execute(`UPDATE ai_analysis_jobs SET status='failed',error_message=?,finished_at=UTC_TIMESTAMP() WHERE id=?`,[message,job.id]);console.error(`Falha na análise de IA #${job.id}:`,error)}}}finally{aiWorkerRunning=false}}
app.get('/api/ai/analysis/base',wrap(async(_req,res)=>{const setting=await getAiSettingsRow();const configuration=publicAiSettings(setting);if(!setting.base_profile_id)return res.json({configuration,analysis:null,job:null,message:'Defina um perfil base para gerar a análise.'});const [latest,jobRows]=await Promise.all([rows<RowDataPacket[]>('SELECT id,profile_id,provider,model,analysis_json,created_at FROM ai_profile_analyses WHERE profile_id=? ORDER BY created_at DESC LIMIT 1',[setting.base_profile_id]),rows<AiJobRow[]>('SELECT * FROM ai_analysis_jobs WHERE profile_id=? ORDER BY created_at DESC LIMIT 1',[setting.base_profile_id])]);const item:any=latest[0];res.json({configuration,job:publicAiJob(jobRows[0]),analysis:item?{id:item.id,profileId:item.profile_id,provider:item.provider,model:item.model,createdAt:item.created_at,...(typeof item.analysis_json==='string'?JSON.parse(item.analysis_json):item.analysis_json)}:null})}));
app.post('/api/ai/analyze-base',rateLimit({windowMs:60_000,limit:4}),wrap(async(req,res)=>{const setting=await getAiSettingsRow();if(!setting.ai_enabled)return res.status(400).json({message:'Ative a inteligência artificial em Configurações.'});if(!setting.base_profile_id)return res.status(400).json({message:'Defina um perfil base antes de gerar a análise.'});configuredAi(setting,setting.ai_provider);const result=await transaction(async connection=>{const [active]=await connection.execute<AiJobRow[]>(`SELECT * FROM ai_analysis_jobs WHERE profile_id=? AND status IN ('queued','running') ORDER BY created_at DESC LIMIT 1 FOR UPDATE`,[setting.base_profile_id]);if(active[0])return{job:active[0],reused:true};const model=setting.ai_provider==='openai'?setting.openai_model:setting.anthropic_model;const [created]=await connection.execute<ResultSetHeader>(`INSERT INTO ai_analysis_jobs(profile_id,provider,model,status,created_by) VALUES(?,?,?,'queued',?)`,[setting.base_profile_id,setting.ai_provider,model,req.user!.id]);const [jobs]=await connection.execute<AiJobRow[]>('SELECT * FROM ai_analysis_jobs WHERE id=?',[created.insertId]);return{job:jobs[0],reused:false}});void processAiQueue();res.status(202).json({job:publicAiJob(result.job),reused:result.reused,message:result.reused?'A análise já está sendo processada em segundo plano.':'Análise iniciada em segundo plano.'})}));
app.get('/api/profiles', wrap(async (req, res) => {
  const q = String(req.query.q || ''); const page = Math.max(1, Number(req.query.page) || 1); const limit = Math.min(100, Math.max(1, Number(req.query.limit) || 20));
  const profiles = await rows<RowDataPacket[]>(`SELECT p.*,s.followers_count,s.posts_count,s.engagement_rate,
    COALESCE((SELECT status FROM collection_batches b WHERE b.profile_id=p.id ORDER BY b.created_at DESC LIMIT 1),(SELECT status FROM apify_runs r WHERE r.profile_id=p.id ORDER BY r.created_at DESC LIMIT 1)) run_status
    FROM instagram_profiles p LEFT JOIN profile_snapshots s ON s.id=(SELECT id FROM profile_snapshots WHERE profile_id=p.id ORDER BY collected_at DESC LIMIT 1)
    WHERE p.username LIKE ? OR COALESCE(p.internal_name,'') LIKE ? ORDER BY p.created_at DESC LIMIT ${limit} OFFSET ${(page-1)*limit}`, [`%${q}%`,`%${q}%`]);
  const count = await rows<(RowDataPacket & { total:number })[]>('SELECT COUNT(*) total FROM instagram_profiles WHERE username LIKE ? OR COALESCE(internal_name,\'\') LIKE ?', [`%${q}%`,`%${q}%`]);
  res.json({ data: profiles, pagination: { page, limit, total: Number(count[0].total) } });
}));
