async function createRun(profileId:number, input:CollectionInput) {
  const reservation=await transaction(async connection=>{
    const [profiles]=await connection.execute<(RowDataPacket&{username:string})[]>('SELECT username FROM instagram_profiles WHERE id=? FOR UPDATE',[profileId]);
    if(!profiles[0]) throw Object.assign(new Error('Perfil não encontrado.'),{status:404});
    const [active]=await connection.execute<(RowDataPacket&{id:number;status:string})[]>(`SELECT id,status FROM apify_runs WHERE profile_id=? AND status IN ('pending','running') ORDER BY created_at DESC LIMIT 1`,[profileId]);
    if(active[0]) return {id:Number(active[0].id),username:profiles[0].username,status:active[0].status,reused:true};
    const [created]=await connection.execute<ResultSetHeader>('INSERT INTO apify_runs(profile_id,collection_type,requested_posts_limit,only_posts_newer_than,only_posts_older_than,status) VALUES(?,?,?,?,?,\'pending\')',[profileId,input.type,input.limit,input.newerThan,input.olderThan]);
    return {id:Number(created.insertId),username:profiles[0].username,status:'pending',reused:false};
  });
  if(reservation.reused)return reservation;
  try {
    const actor=await startActor(reservation.username,input.type,input.limit,input.newerThan);
    await db.execute('UPDATE apify_runs SET apify_run_id=?,apify_dataset_id=?,request_payload=?,status=\'running\',started_at=UTC_TIMESTAMP() WHERE id=?',[actor.runId,actor.datasetId,JSON.stringify({...actor.payload,onlyPostsOlderThan:input.olderThan}),reservation.id]);
    return {...reservation,status:'running'};
  } catch(error) {
    const message=String(error instanceof Error?error.message:error);
    await db.execute('UPDATE apify_runs SET status=\'failed\',finished_at=UTC_TIMESTAMP(),error_message=? WHERE id=?',[message,reservation.id]);
    throw Object.assign(new Error(`Não foi possível iniciar a coleta: ${message}`),{status:502});
  }
}
async function refreshBatchStatus(batchId:number){
  const children=await rows<(RowDataPacket&{status:string;error_message:string|null})[]>('SELECT status,error_message FROM apify_runs WHERE batch_id=?',[batchId]);
  if(!children.length)return 'pending';
  const statuses=children.map(child=>child.status);let status='running';
  if(statuses.every(value=>value==='succeeded'))status='succeeded';
  else if(statuses.some(value=>value==='pending'||value==='running'))status='running';
  else if(statuses.some(value=>value==='failed'))status='failed';
  else if(statuses.some(value=>value==='timed_out'))status='timed_out';
  else status='aborted';
  const error=children.find(child=>child.error_message)?.error_message||null;
  await db.execute(`UPDATE collection_batches SET status=?,started_at=COALESCE(started_at,UTC_TIMESTAMP()),finished_at=IF(?='running',NULL,UTC_TIMESTAMP()),error_message=? WHERE id=?`,[status,status,error,batchId]);
  return status;
}
async function createCollectionBatch(profileId:number,input:CollectionInput){
  const reservation=await transaction(async connection=>{
    const [profiles]=await connection.execute<(RowDataPacket&{username:string})[]>('SELECT username FROM instagram_profiles WHERE id=? FOR UPDATE',[profileId]);
    if(!profiles[0])throw Object.assign(new Error('Perfil não encontrado.'),{status:404});
    const [active]=await connection.execute<(RowDataPacket&{id:number;status:string})[]>(`SELECT id,status FROM collection_batches WHERE profile_id=? AND status IN ('pending','running') ORDER BY created_at DESC LIMIT 1`,[profileId]);
    if(active[0]){const [runs]=await connection.execute<(RowDataPacket&{id:number})[]>('SELECT id FROM apify_runs WHERE batch_id=? ORDER BY id',[active[0].id]);return {batchId:Number(active[0].id),ids:runs.map(run=>Number(run.id)),username:profiles[0].username,reused:true,runs:[] as {id:number;type:'profile_details'|'posts'|'stories';limit:number}[]};}
    const [batch]=await connection.execute<ResultSetHeader>('INSERT INTO collection_batches(profile_id,status) VALUES(?,\'pending\')',[profileId]);const batchId=Number(batch.insertId);
    const definitions:{type:'profile_details'|'posts'|'stories';limit:number}[]=[{type:'profile_details',limit:1},{type:'posts',limit:input.limit},{type:'stories',limit:Math.min(input.limit,50)}];const createdRuns:{id:number;type:'profile_details'|'posts'|'stories';limit:number}[]=[];
    for(const definition of definitions){const [created]=await connection.execute<ResultSetHeader>('INSERT INTO apify_runs(profile_id,batch_id,collection_type,requested_posts_limit,only_posts_newer_than,only_posts_older_than,status) VALUES(?,?,?,?,?,?,\'pending\')',[profileId,batchId,definition.type,definition.limit,input.newerThan,input.olderThan]);createdRuns.push({id:Number(created.insertId),...definition});}
    return {batchId,ids:createdRuns.map(run=>run.id),username:profiles[0].username,reused:false,runs:createdRuns};
  });
  if(reservation.reused)return reservation;
  await Promise.all(reservation.runs.map(async run=>{try{const actor=await startActor(reservation.username,run.type,run.limit,input.newerThan);await db.execute('UPDATE apify_runs SET apify_run_id=?,apify_dataset_id=?,request_payload=?,status=\'running\',started_at=UTC_TIMESTAMP() WHERE id=?',[actor.runId,actor.datasetId,JSON.stringify({...actor.payload,onlyPostsOlderThan:input.olderThan}),run.id]);}catch(error){await db.execute('UPDATE apify_runs SET status=\'failed\',finished_at=UTC_TIMESTAMP(),error_message=? WHERE id=?',[String(error instanceof Error?error.message:error),run.id]);}}));
  await refreshBatchStatus(reservation.batchId);return reservation;
}
app.post('/api/profiles/:id/collect', wrap(async(req,res)=>{ const requested=collectSchema.parse(req.body);const settings=await getCollectionSettings();const input:CollectionInput={...requested,limit:settings.resultsLimit,newerThan:settings.onlyPostsNewerThan,olderThan:settings.postsUntil};if(input.type==='full'){const batch=await createCollectionBatch(idOf(req),input);return res.status(batch.reused?200:202).json({...batch,settings});}const result=await createRun(idOf(req),input);res.status(result.reused?200:202).json({...result,settings}); }));
app.get('/api/runs', wrap(async(req,res)=>{ const status=String(req.query.status||''); const values:unknown[]=[]; const where=status?'WHERE r.status=?':''; if(status) values.push(status);
  res.json(await rows<RowDataPacket[]>(`SELECT r.*,p.username,p.internal_name,TIMESTAMPDIFF(SECOND,r.started_at,r.finished_at) duration_seconds FROM apify_runs r JOIN instagram_profiles p ON p.id=r.profile_id ${where} ORDER BY r.created_at DESC LIMIT 200`,values)); }));
app.delete('/api/runs', wrap(async(_req,res)=>{const result=await transaction(async c=>{const [active]=await c.execute<RowDataPacket[]>(`SELECT id FROM apify_runs WHERE status IN ('pending','running') FOR UPDATE`);if(active.length>0)throw Object.assign(new Error('Cancele ou aguarde as coletas em andamento antes de limpar todo o histórico.'),{status:409});const [deletedRuns]=await c.execute<ResultSetHeader>('DELETE FROM apify_runs');const [deletedBatches]=await c.execute<ResultSetHeader>('DELETE FROM collection_batches');return {runs:deletedRuns.affectedRows,batches:deletedBatches.affectedRows};});res.json({deleted:result});}));
app.delete('/api/collection-batches/:id', wrap(async(req,res)=>{const batchId=idOf(req);const deleted=await transaction(async c=>{const [batch]=await c.execute<RowDataPacket[]>('SELECT id FROM collection_batches WHERE id=? FOR UPDATE',[batchId]);if(!batch[0])throw Object.assign(new Error('Coleta não encontrada.'),{status:404});const [active]=await c.execute<RowDataPacket[]>(`SELECT id FROM apify_runs WHERE batch_id=? AND status IN ('pending','running') FOR UPDATE`,[batchId]);if(active.length>0)throw Object.assign(new Error('Cancele ou aguarde esta coleta antes de limpá-la.'),{status:409});const [runs]=await c.execute<ResultSetHeader>('DELETE FROM apify_runs WHERE batch_id=?',[batchId]);await c.execute('DELETE FROM collection_batches WHERE id=?',[batchId]);return runs.affectedRows;});res.json({deletedRuns:deleted});}));
app.delete('/api/runs/:id', wrap(async(req,res)=>{const runId=idOf(req);await transaction(async c=>{const [found]=await c.execute<(RowDataPacket&{status:string;batch_id:number|null})[]>('SELECT status,batch_id FROM apify_runs WHERE id=? FOR UPDATE',[runId]);if(!found[0])throw Object.assign(new Error('Coleta não encontrada.'),{status:404});if(['pending','running'].includes(found[0].status))throw Object.assign(new Error('Cancele ou aguarde esta coleta antes de limpá-la.'),{status:409});await c.execute('DELETE FROM apify_runs WHERE id=?',[runId]);if(found[0].batch_id)await c.execute('DELETE FROM collection_batches WHERE id=? AND NOT EXISTS(SELECT 1 FROM apify_runs WHERE batch_id=?)',[found[0].batch_id,found[0].batch_id]);});res.status(204).end();}));
app.get('/api/runs/:id', wrap(async(req,res)=>{ const data=await rows<RowDataPacket[]>('SELECT r.*,p.username FROM apify_runs r JOIN instagram_profiles p ON p.id=r.profile_id WHERE r.id=?',[idOf(req)]); if(!data[0]) return res.status(404).json({message:'Coleta não encontrada.'}); res.json(data[0]); }));

async function importRun(localRunId:number) {
  const runs = await rows<(RowDataPacket & {profile_id:number;apify_dataset_id:string;collection_type:string;only_posts_older_than:string|null})[]>('SELECT * FROM apify_runs WHERE id=?',[localRunId]); const initialRun=runs[0]; if(!initialRun) throw new Error('Coleta não encontrada.');
  const items=await getDataset(initialRun.apify_dataset_id);
  await transaction(async c=>{
    const [locked]=await c.execute<(RowDataPacket&{profile_id:number;status:string})[]>('SELECT * FROM apify_runs WHERE id=? FOR UPDATE',[localRunId]);
    const run=locked[0];if(!run)throw new Error('Coleta não encontrada.');if(run.status==='succeeded')return;
    const detail=items.find(i=>i.username && (i.followersCount!=null || i.followers!=null));
    if(detail){ await c.execute(`UPDATE instagram_profiles SET instagram_profile_id=?,full_name=?,biography=?,profile_picture_url=?,external_url=?,category=?,is_verified=?,is_private=?,last_collected_at=UTC_TIMESTAMP() WHERE id=?`,
      [detail.id||null,detail.fullName||null,detail.biography||null,detail.profilePicUrl||detail.profilePicUrlHD||null,detail.externalUrl||null,detail.businessCategoryName||detail.categoryName||null,Boolean(detail.verified),Boolean(detail.private),run.profile_id] as any[]); }
    const [previousSnapshots]=await c.execute<RowDataPacket[]>('SELECT followers_count FROM profile_snapshots WHERE profile_id=? ORDER BY collected_at DESC LIMIT 1',[run.profile_id]);
    const followerCount=Number(detail?.followersCount||detail?.followers||previousSnapshots[0]?.followers_count||0); let likesTotal=0,commentsTotal=0,postCount=0;
    for(const raw of items.filter(i=>i.type || i.shortCode || i.shortcode)) { const post=normalizePost(raw); if(!post.instagramPostId&&!post.shortcode) continue;
      if(initialRun.collection_type==='posts'&&initialRun.only_posts_older_than&&post.publishedAt){const end=new Date(`${String(initialRun.only_posts_older_than).slice(0,10)}T23:59:59.999Z`);if(new Date(post.publishedAt)>end)continue;}
      await c.execute(`INSERT INTO instagram_posts(profile_id,instagram_post_id,shortcode,post_type,content_surface,caption,post_url,display_url,video_url,published_at,duration_seconds,is_paid_partnership,comments_disabled,raw_data)
        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE caption=VALUES(caption),post_type=VALUES(post_type),content_surface=VALUES(content_surface),post_url=VALUES(post_url),display_url=VALUES(display_url),video_url=VALUES(video_url),updated_at=CURRENT_TIMESTAMP`,
        [run.profile_id,post.instagramPostId,post.shortcode,post.type,post.surface,post.caption,post.postUrl,post.displayUrl,post.videoUrl,post.publishedAt,post.duration,post.paid,post.commentsDisabled,JSON.stringify(post.raw)]);
      const [found]=await c.execute<RowDataPacket[]>('SELECT id FROM instagram_posts WHERE profile_id=? AND (instagram_post_id=? OR shortcode=?) LIMIT 1',[run.profile_id,post.instagramPostId,post.shortcode]); const postId=Number(found[0].id); const metric=engagement(post.likes,post.comments,followerCount);
      await c.execute('INSERT IGNORE INTO post_metrics(post_id,apify_run_id,likes_count,comments_count,views_count,plays_count,engagement_count,engagement_rate) VALUES(?,?,?,?,?,?,?,?)',[postId,localRunId,post.likes,post.comments,post.views,post.plays,metric.count,metric.rate]);
      for(const tag of post.hashtags){ await c.execute('INSERT IGNORE INTO hashtags(name) VALUES(?)',[tag]); const [h]=await c.execute<RowDataPacket[]>('SELECT id FROM hashtags WHERE name=?',[tag]); await c.execute('INSERT IGNORE INTO post_hashtags(post_id,hashtag_id) VALUES(?,?)',[postId,h[0].id]); }
      const nestedComments=Array.isArray(raw.latestComments)?raw.latestComments:Array.isArray(raw.comments)?raw.comments:[];
      for(const item of nestedComments as Record<string,unknown>[]){ const commentId=String(item.id||item.commentId||'')||null; if(!commentId) continue;
        await c.execute(`INSERT IGNORE INTO instagram_comments(post_id,instagram_comment_id,text,owner_username,owner_full_name,owner_profile_picture_url,likes_count,replies_count,commented_at,raw_data)
          VALUES(?,?,?,?,?,?,?,?,?,?)`,[postId,commentId,item.text||item.commentText||null,item.ownerUsername||item.owner?.toString()||null,item.ownerFullName||null,item.ownerProfilePicUrl||null,Number(item.likesCount||0),Number(item.repliesCount||0),item.timestamp?new Date(String(item.timestamp)):null,JSON.stringify(item)] as any[]); }
      likesTotal+=post.likes; commentsTotal+=post.comments; postCount++;
    }
    const avgLikes=postCount?likesTotal/postCount:0,avgComments=postCount?commentsTotal/postCount:0,avgEng=avgLikes+avgComments,rate=followerCount?avgEng/followerCount*100:0;
    await c.execute('INSERT INTO profile_snapshots(profile_id,followers_count,follows_count,posts_count,average_likes,average_comments,average_engagement,engagement_rate) VALUES(?,?,?,?,?,?,?,?)',[run.profile_id,followerCount,Number(detail?.followsCount||detail?.following||0),Number(detail?.postsCount||postCount),avgLikes,avgComments,avgEng,rate]);
    await c.execute('UPDATE instagram_profiles SET last_collected_at=UTC_TIMESTAMP() WHERE id=?',[run.profile_id]);
    await c.execute('UPDATE apify_runs SET status=\'succeeded\',finished_at=UTC_TIMESTAMP(),result_summary=? WHERE id=?',[JSON.stringify({itemsProcessed:items.length,postsProcessed:postCount}),localRunId]);
  });
}
async function refreshLocalRun(localId:number){ const found=await rows<(RowDataPacket & {apify_run_id:string;status:string;batch_id:number|null})[]>('SELECT * FROM apify_runs WHERE id=?',[localId]); if(!found[0]) throw Object.assign(new Error('Coleta não encontrada.'),{status:404}); if(!found[0].apify_run_id) throw Object.assign(new Error('Execução não iniciada.'),{status:400});
  const remote=await getRun(found[0].apify_run_id); const mapped:{[key:string]:string}={READY:'running',RUNNING:'running',SUCCEEDED:'succeeded',FAILED:'failed',ABORTED:'aborted',TIMED_OUT:'timed_out'}; const status=mapped[remote.status]||'running';
  if(status==='succeeded'&&found[0].status!=='succeeded'){
    try{await importRun(localId);}catch(error){const message=`A Apify concluiu, mas a importação falhou: ${String(error instanceof Error?error.message:error)}`;await db.execute('UPDATE apify_runs SET status=\'failed\',finished_at=UTC_TIMESTAMP(),error_message=? WHERE id=?',[message,localId]);if(found[0].batch_id)await refreshBatchStatus(Number(found[0].batch_id));throw Object.assign(new Error(message),{status:500});}
  }else await db.execute('UPDATE apify_runs SET status=?,finished_at=IF(?=\'running\',NULL,UTC_TIMESTAMP()),error_message=? WHERE id=?',[status,status,remote.statusMessage||null,localId]);if(found[0].batch_id)await refreshBatchStatus(Number(found[0].batch_id));return status; }
app.post('/api/runs/:id/refresh', wrap(async(req,res)=>{ res.json({status:await refreshLocalRun(idOf(req))}); }));
app.post('/api/runs/:id/retry', wrap(async(req,res)=>{ const run=await rows<(RowDataPacket & {profile_id:number;collection_type:any;requested_posts_limit:number;only_posts_newer_than:string;only_posts_older_than:string|null})[]>('SELECT * FROM apify_runs WHERE id=?',[idOf(req)]); if(!run[0]) return res.status(404).json({message:'Coleta não encontrada.'}); const result=await createRun(run[0].profile_id,{type:run[0].collection_type,limit:run[0].requested_posts_limit,newerThan:run[0].only_posts_newer_than,olderThan:run[0].only_posts_older_than}); res.status(result.reused?200:202).json(result); }));
app.post('/api/runs/:id/abort', wrap(async(req,res)=>{ const run=await rows<(RowDataPacket & {apify_run_id:string;batch_id:number|null})[]>('SELECT * FROM apify_runs WHERE id=?',[idOf(req)]); if(run[0]?.apify_run_id) await abortRun(run[0].apify_run_id); await db.execute('UPDATE apify_runs SET status=\'aborted\',finished_at=UTC_TIMESTAMP() WHERE id=?',[idOf(req)]);if(run[0]?.batch_id)await refreshBatchStatus(Number(run[0].batch_id));res.status(204).end(); }));

const dashboardSql=`SELECT p.*,s.followers_count,s.follows_count,s.posts_count,s.average_likes,s.average_comments,s.average_engagement,s.engagement_rate,
  (SELECT followers_count FROM profile_snapshots WHERE profile_id=p.id AND followers_count>0 ORDER BY collected_at ASC LIMIT 1) first_followers
  FROM instagram_profiles p LEFT JOIN profile_snapshots s ON s.id=(SELECT id FROM profile_snapshots WHERE profile_id=p.id ORDER BY collected_at DESC LIMIT 1) WHERE p.id=?`;
app.get('/api/dashboard/summary', wrap(async(_req,res)=>{ const summary=await rows<RowDataPacket[]>(`SELECT COUNT(*) profiles,COALESCE(SUM(x.followers_count),0) followers,COALESCE(AVG(x.engagement_rate),0) engagement_rate,(SELECT COUNT(*) FROM instagram_posts) posts,(SELECT COUNT(*) FROM apify_runs WHERE status='running') running FROM instagram_profiles p LEFT JOIN profile_snapshots x ON x.id=(SELECT id FROM profile_snapshots WHERE profile_id=p.id ORDER BY collected_at DESC LIMIT 1)`); const top=await rows<RowDataPacket[]>(`${dashboardSql.replace('WHERE p.id=?','')} ORDER BY s.engagement_rate DESC LIMIT 6`); res.json({summary:summary[0],profiles:top}); }));
app.get('/api/dashboard/strategy', wrap(async(req,res)=>{
  const configured=await rows<(RowDataPacket&{base_profile_id:number|null})[]>('SELECT base_profile_id FROM workspace_settings WHERE id=1');
  const profiles=await rows<RowDataPacket[]>(`SELECT p.id,p.username,p.internal_name,p.full_name,p.profile_picture_url,p.last_collected_at,
    COALESCE(s.followers_count,0) followers_count,COALESCE(s.posts_count,0) posts_count,COALESCE(s.average_likes,0) average_likes,
    COALESCE(s.average_comments,0) average_comments,COALESCE(s.average_engagement,0) average_engagement,COALESCE(s.engagement_rate,0) engagement_rate,
    COALESCE((SELECT followers_count FROM profile_snapshots WHERE profile_id=p.id AND followers_count>0 ORDER BY collected_at ASC LIMIT 1),0) first_followers,
    (SELECT COUNT(*) FROM instagram_posts ip WHERE ip.profile_id=p.id AND ip.published_at>=UTC_TIMESTAMP()-INTERVAL 30 DAY) recent_posts
    FROM instagram_profiles p LEFT JOIN profile_snapshots s ON s.id=(SELECT id FROM profile_snapshots WHERE profile_id=p.id ORDER BY collected_at DESC LIMIT 1)
    WHERE p.is_active=1 ORDER BY p.created_at`);
  const formats=await rows<RowDataPacket[]>(`SELECT p.profile_id,p.post_type,COUNT(*) posts,AVG(COALESCE(m.engagement_count,0)) average_engagement
    FROM instagram_posts p LEFT JOIN post_metrics m ON m.id=(SELECT id FROM post_metrics WHERE post_id=p.id ORDER BY collected_at DESC LIMIT 1)
    GROUP BY p.profile_id,p.post_type ORDER BY average_engagement DESC`);
  const baseId=Number(configured[0]?.base_profile_id||0)||null; const requestedId=Number(req.query.profileId||0); const selected=profiles.find((p:any)=>Number(p.id)===(requestedId||baseId||Number(profiles[0]?.id)));
  if(!selected) return res.json({profiles:[],baseProfileId:baseId,selected:null,competitors:[],recommendations:[]});
  const enriched=profiles.map((profile:any)=>{const profileFormats=formats.filter((f:any)=>Number(f.profile_id)===Number(profile.id));const growth=Number(profile.followers_count)-Number(profile.first_followers);return {...profile,growth,growth_percent:Number(profile.first_followers)>0?growth/Number(profile.first_followers)*100:0,best_format:profileFormats[0]?.post_type||null,best_format_engagement:Number(profileFormats[0]?.average_engagement||0)};});
  const current=enriched.find((p:any)=>Number(p.id)===Number(selected.id)); const competitors=enriched.filter((p:any)=>Number(p.id)!==Number(current.id));
  const avg=(key:string)=>competitors.length?competitors.reduce((sum:number,p:any)=>sum+Number(p[key]||0),0)/competitors.length:0; const best=(key:string)=>competitors.length?Math.max(...competitors.map((p:any)=>Number(p[key]||0))):0;
  const recommendations:any[]=[];
  if(!current.last_collected_at) recommendations.push({priority:'high',category:'Dados',title:'Realize a primeira coleta',insight:'Ainda não há dados do Instagram Scraper para este perfil.',action:'Abra o perfil e use “Atualizar Instagram” antes de comparar o desempenho.'});
  else {
    const competitorEngagement=avg('engagement_rate'); if(competitorEngagement>Number(current.engagement_rate)) recommendations.push({priority:'high',category:'Engajamento',title:'Fechar a diferença de engajamento',insight:`O perfil está ${(competitorEngagement-Number(current.engagement_rate)).toFixed(2)} p.p. abaixo da média dos concorrentes.`,action:'Repita temas e formatos dos posts com maior número de comentários e inclua uma chamada clara para interação.'}); else recommendations.push({priority:'positive',category:'Engajamento',title:'Transformar vantagem em consistência',insight:'A taxa de engajamento está acima da média dos concorrentes.',action:'Mantenha o padrão editorial dos conteúdos líderes e teste variações do mesmo tema.'});
    const competitorFrequency=best('recent_posts'); if(competitorFrequency>Number(current.recent_posts)) recommendations.push({priority:'medium',category:'Frequência',title:'Aumentar a cadência de publicação',insight:`O concorrente mais ativo publicou ${competitorFrequency} vezes nos últimos 30 dias; este perfil publicou ${current.recent_posts}.`,action:`Planeje ao menos ${Math.ceil((competitorFrequency-Number(current.recent_posts))/4)} publicação adicional por semana.`});
    const competitorLikes=avg('average_likes'); if(competitorLikes>Number(current.average_likes)) recommendations.push({priority:'medium',category:'Conteúdo',title:'Elevar o potencial de alcance',insight:`A média de curtidas está ${Math.round(competitorLikes-Number(current.average_likes))} abaixo dos concorrentes.`,action:`Priorize ${competitors.sort((a:any,b:any)=>b.best_format_engagement-a.best_format_engagement)[0]?.best_format||'o formato líder'} e adapte os assuntos que já geraram maior engajamento.`});
    if(current.growth<avg('growth')) recommendations.push({priority:'low',category:'Crescimento',title:'Converter engajamento em seguidores',insight:'O crescimento está abaixo da média do grupo monitorado.',action:'Inclua propostas de valor claras no perfil e chamadas para seguir em conteúdos de maior alcance.'});
  }
  const maxValues={followers_count:Math.max(1,...enriched.map((p:any)=>Number(p.followers_count))),engagement_rate:Math.max(1,...enriched.map((p:any)=>Number(p.engagement_rate))),recent_posts:Math.max(1,...enriched.map((p:any)=>Number(p.recent_posts))),average_likes:Math.max(1,...enriched.map((p:any)=>Number(p.average_likes))),growth:Math.max(1,...enriched.map((p:any)=>Math.max(0,Number(p.growth))))};
  const score=(profile:any)=>[{metric:'Audiência',score:Number(profile.followers_count)/maxValues.followers_count*100},{metric:'Engajamento',score:Number(profile.engagement_rate)/maxValues.engagement_rate*100},{metric:'Frequência',score:Number(profile.recent_posts)/maxValues.recent_posts*100},{metric:'Curtidas',score:Number(profile.average_likes)/maxValues.average_likes*100},{metric:'Crescimento',score:Math.max(0,Number(profile.growth))/maxValues.growth*100}];
  res.json({profiles:enriched,baseProfileId:baseId,selected:current,competitors,recommendations:recommendations.slice(0,4),scores:enriched.map((p:any)=>({id:p.id,username:p.username,values:score(p)}))});
}));
app.post('/api/profiles/:id/set-base', wrap(async(req,res)=>{const profileId=idOf(req);const found=await rows<RowDataPacket[]>('SELECT id FROM instagram_profiles WHERE id=?',[profileId]);if(!found[0])return res.status(404).json({message:'Perfil não encontrado.'});await db.execute(`INSERT INTO workspace_settings(id,base_profile_id,updated_by) VALUES(1,?,?) ON DUPLICATE KEY UPDATE base_profile_id=VALUES(base_profile_id),updated_by=VALUES(updated_by)`,[profileId,req.user!.id]);res.json({baseProfileId:profileId});}));
app.get('/api/profiles/:id/dashboard', wrap(async(req,res)=>{ const id=idOf(req); const profile=await rows<RowDataPacket[]>(dashboardSql,[id]); const history=await rows<RowDataPacket[]>('SELECT followers_count,average_engagement,engagement_rate,collected_at FROM profile_snapshots WHERE profile_id=? ORDER BY collected_at',[id]); const formats=await rows<RowDataPacket[]>(`SELECT p.post_type name,COUNT(*) posts,AVG(m.engagement_count) engagement FROM instagram_posts p LEFT JOIN post_metrics m ON m.id=(SELECT id FROM post_metrics WHERE post_id=p.id ORDER BY collected_at DESC LIMIT 1) WHERE p.profile_id=? GROUP BY p.post_type`,[id]); const topPosts=await rows<RowDataPacket[]>(`SELECT p.*,m.likes_count,m.comments_count,m.views_count,m.plays_count,m.engagement_rate FROM instagram_posts p LEFT JOIN post_metrics m ON m.id=(SELECT id FROM post_metrics WHERE post_id=p.id ORDER BY collected_at DESC LIMIT 1) WHERE p.profile_id=? ORDER BY m.engagement_count DESC LIMIT 8`,[id]); res.json({profile:profile[0],history,formats,topPosts}); }));
app.get('/api/profiles/:id/content-dashboard', wrap(async(req,res)=>{
  const id=idOf(req); const from=String(req.query.from||''); const to=String(req.query.to||''); const type=String(req.query.type||''); const search=String(req.query.search||'').trim();
  const values:any[]=[id]; let where='p.profile_id=?';
  if(from){ where+=' AND p.published_at>=?'; values.push(`${from} 00:00:00`); }
  if(to){ where+=' AND p.published_at<=?'; values.push(`${to} 23:59:59`); }
  if(type){ where+=' AND p.post_type=?'; values.push(type); }
  if(search){ where+=' AND (p.caption LIKE ? OR EXISTS(SELECT 1 FROM post_hashtags px JOIN hashtags hx ON hx.id=px.hashtag_id WHERE px.post_id=p.id AND hx.name LIKE ?))'; values.push(`%${search}%`,`%${search.replace(/^#/,'')}%`); }
  const profile=(await rows<RowDataPacket[]>(dashboardSql,[id]))[0]; if(!profile) return res.status(404).json({message:'Perfil não encontrado.'});
  const posts=await rows<RowDataPacket[]>(`SELECT p.id,p.shortcode,p.post_type,p.caption,p.post_url,p.display_url,p.published_at,p.duration_seconds,
    COALESCE(m.likes_count,0) likes_count,COALESCE(m.comments_count,0) comments_count,COALESCE(m.views_count,0) views_count,
    COALESCE(m.plays_count,0) plays_count,COALESCE(m.engagement_count,0) engagement_count,COALESCE(m.engagement_rate,0) engagement_rate,
    COALESCE((SELECT GROUP_CONCAT(h.name ORDER BY h.name SEPARATOR ',') FROM post_hashtags ph JOIN hashtags h ON h.id=ph.hashtag_id WHERE ph.post_id=p.id),'') hashtags
    FROM instagram_posts p LEFT JOIN post_metrics m ON m.id=(SELECT id FROM post_metrics WHERE post_id=p.id ORDER BY collected_at DESC LIMIT 1)
    WHERE ${where} ORDER BY p.published_at DESC LIMIT 1000`,values);
  const totals=posts.reduce((a:any,p:any)=>{a.likes+=Number(p.likes_count);a.comments+=Number(p.comments_count);a.views+=Number(p.views_count);a.plays+=Number(p.plays_count);a.engagement+=Number(p.engagement_count);return a;},{likes:0,comments:0,views:0,plays:0,engagement:0});
  const buckets=(keyOf:(post:any)=>string)=>{const map=new Map<string,any>(); for(const post of posts){const key=keyOf(post); const item=map.get(key)||{key,posts:0,likes:0,comments:0,views:0,plays:0,engagement:0};item.posts++;item.likes+=Number(post.likes_count);item.comments+=Number(post.comments_count);item.views+=Number(post.views_count);item.plays+=Number(post.plays_count);item.engagement+=Number(post.engagement_count);map.set(key,item);}return [...map.values()];};
  const monthly=buckets(p=>{const d=new Date(p.published_at);return `${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}`;}).sort((a,b)=>a.key.localeCompare(b.key));
  const formats=buckets(p=>p.post_type).map(x=>({...x,averageEngagement:x.posts?x.engagement/x.posts:0})).sort((a,b)=>b.averageEngagement-a.averageEngagement);
  const weekdaysNames=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb']; const weekdays=buckets(p=>weekdaysNames[new Date(p.published_at).getUTCDay()]).map(x=>({...x,order:weekdaysNames.indexOf(x.key),averageEngagement:x.posts?x.engagement/x.posts:0})).sort((a,b)=>a.order-b.order);
  const hashtagMap=new Map<string,any>(); for(const post of posts){for(const tag of String(post.hashtags||'').split(',').filter(Boolean)){const item=hashtagMap.get(tag)||{name:tag,uses:0,engagement:0};item.uses++;item.engagement+=Number(post.engagement_count);hashtagMap.set(tag,item);}}
  const hashtags=[...hashtagMap.values()].sort((a,b)=>b.engagement-a.engagement).slice(0,20); const ranked=[...posts].sort((a:any,b:any)=>Number(b.engagement_count)-Number(a.engagement_count));
  const days=posts.length?Math.max(1,(Math.max(...posts.map((p:any)=>+new Date(p.published_at)))-Math.min(...posts.map((p:any)=>+new Date(p.published_at))))/86400000):0;
  res.json({profile,summary:{posts:posts.length,...totals,averageEngagement:posts.length?totals.engagement/posts.length:0,averageLikes:posts.length?totals.likes/posts.length:0,averageComments:posts.length?totals.comments/posts.length:0,frequencyPerWeek:days?posts.length/days*7:posts.length},monthly,formats,weekdays,hashtags,posts:ranked,
    insights:{bestFormat:formats[0]?.key||null,bestDay:[...weekdays].sort((a,b)=>b.averageEngagement-a.averageEngagement)[0]?.key||null,topPost:ranked[0]||null}});
}));
app.get('/api/profiles/:id/posts', wrap(async(req,res)=>{ const id=idOf(req),page=Math.max(1,Number(req.query.page)||1),limit=Math.min(100,Math.max(1,Number(req.query.limit)||20)); const type=String(req.query.type||''),search=String(req.query.search||''); const values:unknown[]=[id]; let where='p.profile_id=?'; if(type){where+=' AND p.post_type=?';values.push(type);} if(search){where+=' AND p.caption LIKE ?';values.push(`%${search}%`);} const data=await rows<RowDataPacket[]>(`SELECT p.*,m.likes_count,m.comments_count,m.views_count,m.plays_count,m.engagement_rate FROM instagram_posts p LEFT JOIN post_metrics m ON m.id=(SELECT id FROM post_metrics WHERE post_id=p.id ORDER BY collected_at DESC LIMIT 1) WHERE ${where} ORDER BY p.published_at DESC LIMIT ${limit} OFFSET ${(page-1)*limit}`,values); res.json({data,pagination:{page,limit}}); }));
app.get('/api/profiles/:id/hashtags', wrap(async(req,res)=>{ res.json(await rows<RowDataPacket[]>(`SELECT h.name,COUNT(*) uses,AVG(m.engagement_count) average_engagement FROM post_hashtags ph JOIN hashtags h ON h.id=ph.hashtag_id JOIN instagram_posts p ON p.id=ph.post_id LEFT JOIN post_metrics m ON m.id=(SELECT id FROM post_metrics WHERE post_id=p.id ORDER BY collected_at DESC LIMIT 1) WHERE p.profile_id=? GROUP BY h.id ORDER BY average_engagement DESC LIMIT 50`,[idOf(req)])); }));
