app.get('/api/posts/:id/dashboard', wrap(async(req,res)=>{
  const postId=idOf(req);const posts=await rows<RowDataPacket[]>(`SELECT p.*,pr.username,pr.full_name,pr.profile_picture_url,
    COALESCE(m.likes_count,0) likes_count,COALESCE(m.comments_count,0) comments_count,COALESCE(m.views_count,0) views_count,
    COALESCE(m.plays_count,0) plays_count,COALESCE(m.engagement_count,0) engagement_count,COALESCE(m.engagement_rate,0) engagement_rate,
    COALESCE((SELECT GROUP_CONCAT(h.name ORDER BY h.name SEPARATOR ',') FROM post_hashtags ph JOIN hashtags h ON h.id=ph.hashtag_id WHERE ph.post_id=p.id),'') hashtags,
    COALESCE((SELECT followers_count FROM profile_snapshots WHERE profile_id=p.profile_id ORDER BY collected_at DESC LIMIT 1),0) followers_count
    FROM instagram_posts p JOIN instagram_profiles pr ON pr.id=p.profile_id
    LEFT JOIN post_metrics m ON m.id=(SELECT id FROM post_metrics WHERE post_id=p.id ORDER BY collected_at DESC LIMIT 1) WHERE p.id=?`,[postId]);
  const post=posts[0];if(!post)return res.status(404).json({message:'Publicação não encontrada.'});
  const history=await rows<RowDataPacket[]>('SELECT likes_count,comments_count,views_count,plays_count,engagement_count,engagement_rate,collected_at FROM post_metrics WHERE post_id=? ORDER BY collected_at',[postId]);
  const comments=await rows<RowDataPacket[]>('SELECT id,text,owner_username,owner_full_name,owner_profile_picture_url,likes_count,replies_count,commented_at FROM instagram_comments WHERE post_id=? ORDER BY commented_at DESC LIMIT 100',[postId]);
  const ranking=await rows<(RowDataPacket&{position:number;total:number})[]>(`SELECT 1+SUM(CASE WHEN latest.engagement_count>? THEN 1 ELSE 0 END) position,COUNT(*) total FROM (
    SELECT ip.id,COALESCE((SELECT engagement_count FROM post_metrics WHERE post_id=ip.id ORDER BY collected_at DESC LIMIT 1),0) engagement_count
    FROM instagram_posts ip WHERE ip.profile_id=?) latest`,[Number(post.engagement_count),Number(post.profile_id)]);
  const first=history[0]||{},latest=history[history.length-1]||{};const daysOnline=Math.max(1,Math.ceil((Date.now()-new Date(post.published_at).getTime())/86400000));
  const growth={likes:Number(latest.likes_count||0)-Number(first.likes_count||0),comments:Number(latest.comments_count||0)-Number(first.comments_count||0),views:Number(latest.views_count||0)-Number(first.views_count||0),plays:Number(latest.plays_count||0)-Number(first.plays_count||0),engagement:Number(latest.engagement_count||0)-Number(first.engagement_count||0)};
  res.json({post,history,comments,growth,ranking:ranking[0],daysOnline,engagementPerDay:Number(post.engagement_count)/daysOnline,historyNotice:history.length<2?'A evolução começará a aparecer após uma nova coleta deste perfil.':'Cada ponto representa uma coleta real do Instagram Scraper.'});
}));

app.post('/api/comparisons/preview', wrap(async(req,res)=>{ const ids=z.object({profileIds:z.array(z.number().int().positive()).min(2).max(10)}).parse(req.body).profileIds; const marks=ids.map(()=>'?').join(','); const data=await rows<RowDataPacket[]>(`${dashboardSql.replace('WHERE p.id=?',`WHERE p.id IN (${marks})`)}`,ids); const history=await rows<RowDataPacket[]>(`SELECT s.*,p.username FROM profile_snapshots s JOIN instagram_profiles p ON p.id=s.profile_id WHERE s.profile_id IN (${marks}) ORDER BY s.collected_at`,ids); res.json({profiles:data,history}); }));
app.get('/api/comparisons/dashboard', wrap(async(req,res)=>{
  const allProfiles=await rows<RowDataPacket[]>(`SELECT p.id,p.username,p.full_name,p.internal_name,p.profile_picture_url,
    COALESCE(s.followers_count,0) followers_count,COALESCE(s.engagement_rate,0) current_engagement_rate
    FROM instagram_profiles p LEFT JOIN profile_snapshots s ON s.id=(SELECT id FROM profile_snapshots WHERE profile_id=p.id ORDER BY collected_at DESC LIMIT 1)
    WHERE p.is_active=1 ORDER BY p.created_at`);
  const setting=await rows<(RowDataPacket&{base_profile_id:number|null})[]>('SELECT base_profile_id FROM workspace_settings WHERE id=1'); const baseProfileId=Number(setting[0]?.base_profile_id||0)||null;
  const requested=String(req.query.profileIds||'').split(',').map(Number).filter(Number.isInteger).filter(id=>allProfiles.some((p:any)=>Number(p.id)===id));
  const ids=[...new Set([...(baseProfileId?[baseProfileId]:[]),...(requested.length?requested:allProfiles.map((p:any)=>Number(p.id)))])].slice(0,10);
  const period=z.enum(['day','week','month','custom']).catch('month').parse(req.query.period); const now=new Date(); let from=new Date(now); let to=new Date(now);
  if(period==='day') from.setUTCHours(0,0,0,0); else if(period==='week') from=new Date(now.getTime()-6*86400000); else if(period==='month') from=new Date(now.getTime()-29*86400000); else {from=new Date(String(req.query.from||''));to=new Date(String(req.query.to||''));if(Number.isNaN(+from)||Number.isNaN(+to))return res.status(400).json({message:'Informe data inicial e final válidas.'});}
  from.setUTCHours(0,0,0,0);to.setUTCHours(23,59,59,999);if(to<from)return res.status(400).json({message:'A data final deve ser posterior à inicial.'});if((+to-+from)/86400000>366)return res.status(400).json({message:'O período máximo é de 366 dias.'});
  if(!ids.length)return res.json({profiles:allProfiles,selectedProfiles:[],baseProfileId,period:{type:period,from,to},summaries:[],daily:[],formats:[],weekdays:[],topPosts:[]});
  const marks=ids.map(()=>'?').join(','); const selectedProfiles=allProfiles.filter((p:any)=>ids.includes(Number(p.id)));
  const posts=await rows<RowDataPacket[]>(`SELECT p.id,p.profile_id,p.shortcode,p.post_type,p.content_surface,p.caption,p.post_url,p.display_url,p.published_at,
    COALESCE(m.likes_count,0) likes_count,COALESCE(m.comments_count,0) comments_count,COALESCE(m.views_count,0) views_count,
    COALESCE(m.plays_count,0) plays_count,COALESCE(m.engagement_count,0) engagement_count
    FROM instagram_posts p LEFT JOIN post_metrics m ON m.id=(SELECT id FROM post_metrics WHERE post_id=p.id ORDER BY collected_at DESC LIMIT 1)
    WHERE p.profile_id IN (${marks}) AND p.published_at BETWEEN ? AND ? ORDER BY p.published_at`,[...ids,from,to]);
  const days=Math.max(1,Math.floor((+to-+from)/86400000)+1); const weekdaysNames=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];
  const label=(post:any)=>post.content_surface==='Story'?'Story':post.content_surface==='Reel'||post.post_type==='Reel'?'Reel':post.post_type==='Sidecar'?'Carrossel':post.post_type==='Image'?'Imagem':post.post_type==='Video'?'Vídeo':'Outro';
  const dailyMap=new Map<string,any>(); const formatMap=new Map<string,any>(); const weekdayMap=new Map<string,any>();
  for(const post of posts as any[]){const username=selectedProfiles.find((p:any)=>Number(p.id)===Number(post.profile_id))?.username||String(post.profile_id);const dateKey=new Date(post.published_at).toISOString().slice(0,10);const dKey=`${post.profile_id}:${dateKey}`;const daily=dailyMap.get(dKey)||{date:dateKey,profileId:Number(post.profile_id),username,posts:0,engagement:0,likes:0,comments:0,plays:0,views:0,reels:0,stories:0};daily.posts++;daily.engagement+=Number(post.engagement_count);daily.likes+=Number(post.likes_count);daily.comments+=Number(post.comments_count);daily.plays+=Number(post.plays_count);daily.views+=Number(post.views_count);if(label(post)==='Reel')daily.reels++;if(label(post)==='Story')daily.stories++;dailyMap.set(dKey,daily);
    const format=label(post),fKey=`${post.profile_id}:${format}`;const f=formatMap.get(fKey)||{profileId:Number(post.profile_id),username,format,posts:0,engagement:0,likes:0,comments:0,plays:0,views:0};f.posts++;f.engagement+=Number(post.engagement_count);f.likes+=Number(post.likes_count);f.comments+=Number(post.comments_count);f.plays+=Number(post.plays_count);f.views+=Number(post.views_count);formatMap.set(fKey,f);
    const weekday=weekdaysNames[new Date(post.published_at).getUTCDay()],wKey=`${post.profile_id}:${weekday}`;const w=weekdayMap.get(wKey)||{profileId:Number(post.profile_id),username,weekday,order:weekdaysNames.indexOf(weekday),posts:0,engagement:0};w.posts++;w.engagement+=Number(post.engagement_count);weekdayMap.set(wKey,w);}
  const daily:any[]=[];for(const id of ids){const username=selectedProfiles.find((p:any)=>Number(p.id)===id)?.username;for(let cursor=new Date(from);cursor<=to;cursor=new Date(cursor.getTime()+86400000)){const key=cursor.toISOString().slice(0,10);daily.push(dailyMap.get(`${id}:${key}`)||{date:key,profileId:id,username,posts:0,engagement:0,likes:0,comments:0,plays:0,views:0,reels:0,stories:0});}}
  const formats=[...formatMap.values()].map((f:any)=>({...f,averageEngagement:f.posts?f.engagement/f.posts:0}));const weekdays=[...weekdayMap.values()].map((w:any)=>({...w,averageEngagement:w.posts?w.engagement/w.posts:0}));
  const summaries=selectedProfiles.map((profile:any)=>{const own=(posts as any[]).filter(p=>Number(p.profile_id)===Number(profile.id));const sum=(key:string)=>own.reduce((total,p)=>total+Number(p[key]||0),0);const ownFormats=formats.filter((f:any)=>f.profileId===Number(profile.id)).sort((a:any,b:any)=>b.averageEngagement-a.averageEngagement);const ownDays=weekdays.filter((w:any)=>w.profileId===Number(profile.id)).sort((a:any,b:any)=>b.averageEngagement-a.averageEngagement);const engagement=sum('engagement_count');return {...profile,posts:own.length,reels:own.filter(p=>label(p)==='Reel').length,stories:own.filter(p=>label(p)==='Story').length,feed:own.filter(p=>!['Reel','Story'].includes(label(p))).length,likes:sum('likes_count'),comments:sum('comments_count'),plays:sum('plays_count'),views:sum('views_count'),engagement,averageEngagement:own.length?engagement/own.length:0,averageLikes:own.length?sum('likes_count')/own.length:0,averageComments:own.length?sum('comments_count')/own.length:0,engagementRate:own.length&&Number(profile.followers_count)?engagement/own.length/Number(profile.followers_count)*100:0,publicationsPerWeek:own.length/days*7,bestFormat:ownFormats[0]?.format||null,bestDay:ownDays[0]?.weekday||null};});
  const topPosts=ids.flatMap(id=>(posts as any[]).filter(p=>Number(p.profile_id)===id).sort((a,b)=>Number(b.engagement_count)-Number(a.engagement_count)).slice(0,4).map(p=>({...p,username:selectedProfiles.find((x:any)=>Number(x.id)===id)?.username,format:label(p)})));
  const top10=(posts as any[]).sort((a,b)=>Number(b.engagement_count)-Number(a.engagement_count)).slice(0,10).map((post,index)=>({...post,position:index+1,username:selectedProfiles.find((p:any)=>Number(p.id)===Number(post.profile_id))?.username,format:label(post)}));
  res.json({profiles:allProfiles,selectedProfiles,baseProfileId,period:{type:period,from,to,days},summaries,daily,formats,weekdays,topPosts,top10,
    posts:(posts as any[]).map(post=>({...post,username:selectedProfiles.find((p:any)=>Number(p.id)===Number(post.profile_id))?.username,format:label(post)}))});
}));
app.post('/api/comparisons', wrap(async(req,res)=>{ const input=z.object({name:z.string().min(2),description:z.string().optional(),profileIds:z.array(z.number()).min(2)}).parse(req.body); const [created]=await db.execute<ResultSetHeader>('INSERT INTO comparison_groups(name,description,created_by) VALUES(?,?,?)',[input.name,input.description||null,req.user!.id]); for(const [order,id] of input.profileIds.entries()) await db.execute('INSERT INTO comparison_group_profiles VALUES(?,?,?)',[created.insertId,id,order]); res.status(201).json({id:created.insertId}); }));
app.get('/api/comparisons/:id', wrap(async(req,res)=>{ const group=await rows<RowDataPacket[]>('SELECT * FROM comparison_groups WHERE id=?',[idOf(req)]);if(!group[0])return res.status(404).json({message:'Grupo não encontrado.'}); const profiles=await rows<RowDataPacket[]>('SELECT p.* FROM comparison_group_profiles gp JOIN instagram_profiles p ON p.id=gp.profile_id WHERE gp.comparison_group_id=? ORDER BY gp.display_order',[idOf(req)]); res.json({group:group[0],profiles}); }));
app.get('/api/comparison-groups', wrap(async(_req,res)=>{ res.json(await rows<RowDataPacket[]>(`SELECT g.*,COUNT(gp.profile_id) profile_count,COALESCE(GROUP_CONCAT(gp.profile_id ORDER BY gp.display_order SEPARATOR ','),'') profile_ids FROM comparison_groups g LEFT JOIN comparison_group_profiles gp ON gp.comparison_group_id=g.id GROUP BY g.id ORDER BY g.created_at DESC`)); }));
const comparisonGroupSchema=z.object({name:z.string().trim().min(2).max(150),description:z.string().trim().max(1000).optional(),profileIds:z.array(z.number().int().positive()).max(10).optional()});
app.post('/api/comparison-groups', wrap(async(req,res)=>{ const input=comparisonGroupSchema.parse(req.body);const profileIds=[...new Set(input.profileIds||[])];const id=await transaction(async c=>{if(profileIds.length){const marks=profileIds.map(()=>'?').join(',');const [found]=await c.execute<RowDataPacket[]>(`SELECT id FROM instagram_profiles WHERE is_active=1 AND id IN (${marks})`,profileIds);if(found.length!==profileIds.length)throw Object.assign(new Error('Um ou mais perfis não estão disponíveis.'),{status:400});}const [result]=await c.execute<ResultSetHeader>('INSERT INTO comparison_groups(name,description,created_by) VALUES(?,?,?)',[input.name,input.description||null,req.user!.id]);for(const [order,profileId] of profileIds.entries())await c.execute('INSERT INTO comparison_group_profiles VALUES(?,?,?)',[result.insertId,profileId,order]);return result.insertId;});res.status(201).json({id}); }));
app.put('/api/comparison-groups/:id', wrap(async(req,res)=>{ const groupId=idOf(req);const input=comparisonGroupSchema.parse(req.body);const profileIds=input.profileIds?[...new Set(input.profileIds)]:undefined;await transaction(async c=>{if(profileIds?.length){const marks=profileIds.map(()=>'?').join(',');const [found]=await c.execute<RowDataPacket[]>(`SELECT id FROM instagram_profiles WHERE is_active=1 AND id IN (${marks})`,profileIds);if(found.length!==profileIds.length)throw Object.assign(new Error('Um ou mais perfis não estão disponíveis.'),{status:400});}const [updated]=await c.execute<ResultSetHeader>('UPDATE comparison_groups SET name=?,description=? WHERE id=?',[input.name,input.description||null,groupId]);if(!updated.affectedRows)throw Object.assign(new Error('Grupo não encontrado.'),{status:404});if(profileIds){await c.execute('DELETE FROM comparison_group_profiles WHERE comparison_group_id=?',[groupId]);for(const [order,profileId] of profileIds.entries())await c.execute('INSERT INTO comparison_group_profiles VALUES(?,?,?)',[groupId,profileId,order]);}});res.status(204).end(); }));
app.delete('/api/comparison-groups/:id', wrap(async(req,res)=>{ await db.execute('DELETE FROM comparison_groups WHERE id=?',[idOf(req)]); res.status(204).end(); }));

function csvCell(value:unknown){ return `"${String(value??'').replaceAll('"','""')}"`; }
app.get('/api/profiles/:id/export.csv', wrap(async(req,res)=>{ const data=await rows<RowDataPacket[]>(`SELECT p.shortcode,p.post_type,p.caption,p.post_url,p.published_at,m.likes_count,m.comments_count,m.views_count,m.plays_count,m.engagement_rate FROM instagram_posts p LEFT JOIN post_metrics m ON m.id=(SELECT id FROM post_metrics WHERE post_id=p.id ORDER BY collected_at DESC LIMIT 1) WHERE p.profile_id=? ORDER BY p.published_at DESC`,[idOf(req)]); const columns=['shortcode','post_type','caption','post_url','published_at','likes_count','comments_count','views_count','plays_count','engagement_rate']; const csv='\uFEFF'+[columns.join(';'),...data.map(row=>columns.map(c=>csvCell(row[c])).join(';'))].join('\n'); res.type('text/csv').attachment('instagram-posts.csv').send(csv); }));
app.post('/api/comparisons/export.csv', wrap(async(req,res)=>{ const ids=z.object({profileIds:z.array(z.number()).min(2)}).parse(req.body).profileIds; const marks=ids.map(()=>'?').join(','); const data=await rows<RowDataPacket[]>(`${dashboardSql.replace('WHERE p.id=?',`WHERE p.id IN (${marks})`)}`,ids); const columns=['username','followers_count','posts_count','average_likes','average_comments','average_engagement','engagement_rate']; const csv='\uFEFF'+[columns.join(';'),...data.map(row=>columns.map(c=>csvCell(row[c])).join(';'))].join('\n'); res.type('text/csv').attachment('comparacao-perfis.csv').send(csv); }));

const dist=resolve('dist'); if(existsSync(dist)){ app.use(express.static(dist)); app.use((req,res,next)=>req.method==='GET'&&!req.path.startsWith('/api/')?res.sendFile(resolve(dist,'index.html')):next()); }
app.use((error:any,_req:Request,res:Response,_next:NextFunction)=>{ if(error instanceof z.ZodError){const issue=error.issues[0];const field=issue?.path?.length?`${issue.path.join('.')}: `:'';return res.status(400).json({message:`${field}${issue?.message||'Dados inválidos.'}`,issues:error.issues});} console.error(error); res.status(error.status||500).json({message:error.status?error.message:'Erro interno do servidor.'}); });

async function bootstrap(){ await initializeDatabase(); app.listen(env.PORT,()=>console.log(`Studek Analytics disponível na porta ${env.PORT}`));void processAiQueue();setInterval(()=>void processAiQueue(),5_000).unref();
  let polling=false; setInterval(async()=>{ if(polling)return; polling=true; try{ const active=await rows<(RowDataPacket&{id:number})[]>('SELECT id FROM apify_runs WHERE status=\'running\' ORDER BY created_at LIMIT 20'); await Promise.allSettled(active.map(run=>refreshLocalRun(run.id))); }finally{polling=false;} },env.COLLECTION_POLL_INTERVAL_SECONDS*1000).unref(); }
bootstrap().catch(error=>{ console.error('Falha ao iniciar:',error); process.exit(1); });
